MATCH (g:Gene)
WHERE g.geneSymbol IN ["PRPSAP1", "PRPS2", "LINC02731", "PRPSAP2", "PRPS1"]
  AND NOT (
    EXISTS { MATCH (g)-[:GENEASSOCIATEDWITHCELLULARCOMPONENT]->(:CellularComponent {commonName: "transferase complex"}) }
    AND EXISTS { MATCH (g)-[:GENEASSOCIATEDWITHCELLULARCOMPONENT]->(:CellularComponent {commonName: "transferring phosphorus-containing groups"}) }
    AND EXISTS { MATCH (g)-[:GENEASSOCIATEDWITHCELLULARCOMPONENT]->(:CellularComponent {commonName: "ribose phosphate diphosphokinase complex"}) }
  )
RETURN g

MATCH (bp:BodyPart)
WHERE bp.commonName IN ["adrenal gland","myometrium","tibial nerve","endometrium","nipple"]
  AND NOT (
    EXISTS {
      MATCH (bp)-[:BODYPARTOVEREXPRESSESGENE]->(g1:Gene)
      WHERE g1.geneSymbol = "MID1"
    }
    AND
    EXISTS {
      MATCH (bp)-[:BODYPARTOVEREXPRESSESGENE]->(g2:Gene)
      WHERE g2.geneSymbol = "RPS16"
    }
  )
RETURN bp
